-- LOCAL PRO ONLY: private commercial stages over existing appointment requests.
-- No existing writer/function/column replacement, public-state changes or sends.
begin;
create table if not exists public.pro_request_pipeline_heads(owner_id uuid primary key references profiles(id) on delete cascade,revision integer not null check(revision>=0));
create table if not exists public.pro_request_pipeline_stages(owner_id uuid not null references profiles(id) on delete cascade,id text not null,name text,position integer not null check(position between 0 and 17),hidden boolean not null default false,retired boolean not null default false,reassign_to_id text,primary key(owner_id,id),foreign key(owner_id,reassign_to_id) references pro_request_pipeline_stages(owner_id,id) deferrable initially deferred,check(hidden=(reassign_to_id is not null)),check(reassign_to_id is distinct from id),check(id not in('new','won') or not hidden),check(id not in('new','followed_up','connected','meeting_scheduled','estimate_sent','won') or not retired),check(case when id in('new','followed_up','connected','meeting_scheduled','estimate_sent','won') then name is null else name is not null and id~'^[a-f0-9-]{36}$' and length(btrim(name)) between 1 and 25 and name!~'[[:cntrl:]]' end));
create table if not exists public.pro_request_pipeline_states(owner_id uuid not null,request_id uuid not null,mode text not null check(mode in('automatic','manual')),stage_id text,revision integer not null check(revision>0),updated_at timestamptz not null default now(),primary key(owner_id,request_id),foreign key(owner_id,request_id) references pro_appointment_requests(owner_id,id) on delete cascade,foreign key(owner_id,stage_id) references pro_request_pipeline_stages(owner_id,id),check((mode='manual')=(stage_id is not null)));
create table if not exists public.pro_request_pipeline_actions(owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,actor_name text not null,at timestamptz not null default now(),primary key(owner_id,action_id));
create table if not exists public.pro_request_pipeline_history(owner_id uuid not null,request_id uuid not null,action_id uuid not null,action text not null check(action in('set_stage','return_auto','reassign_stage')),before_state jsonb not null,after_state jsonb not null,before_name text,after_name text,at timestamptz not null default now(),primary key(owner_id,request_id,action_id),foreign key(owner_id,request_id) references pro_appointment_requests(owner_id,id) on delete cascade);
create or replace function public.pro_request_pipeline_owner(p_actor uuid) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$begin if not coalesce(pro_appointment_enabled(p_actor),false) or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;end $$;
create or replace function public.pro_request_pipeline_catalog(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare stages jsonb;begin perform pro_request_pipeline_owner(p_actor);
 with defaults as(select v id,(n-1)::integer position from unnest(array['new','followed_up','connected','meeting_scheduled','estimate_sent','won']) with ordinality x(v,n)),all_stages as(select d.id,coalesce(s.position,d.position)position,s.name,coalesce(s.hidden,false)hidden,s.reassign_to_id,true builtin from defaults d left join pro_request_pipeline_stages s on s.owner_id=p_actor and s.id=d.id union all select id,position,name,hidden,reassign_to_id,false from pro_request_pipeline_stages where owner_id=p_actor and not retired and id not in('new','followed_up','connected','meeting_scheduled','estimate_sent','won')) select jsonb_agg(jsonb_build_object('id',id,'builtin',builtin,'name',name,'position',position,'hidden',hidden,'reassignToId',reassign_to_id) order by position) into stages from all_stages;
 return jsonb_build_object('revision',coalesce((select revision from pro_request_pipeline_heads where owner_id=p_actor),0),'stages',stages);end $$;
create or replace function public.pro_request_pipeline_state(p_actor uuid,p_request uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$ select jsonb_build_object('requestId',p_request,'mode',coalesce(s.mode,'automatic'),'stageId',s.stage_id,'revision',coalesce(s.revision,0),'updatedAt',s.updated_at) from(select 1)dummy left join pro_request_pipeline_states s on s.owner_id=p_actor and s.request_id=p_request $$;
create or replace function public.pro_request_pipeline_auto(p_actor uuid,p_request uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_appointment_requests;q quotes;e pro_appointment_events;record jsonb;begin
 select * into r from pro_appointment_requests where owner_id=p_actor and id=p_request;if not found then raise exception 'Request unavailable' using errcode='P0002';end if;
 select x.* into q from pro_request_quotes m join quotes x on x.id=m.quote_id join professionals p on p.id=x.professional_id and p.profile_id=p_actor where m.owner_id=p_actor and m.request_id=r.id and m.client_user_id=r.client_user_id and x.client_id=r.client_user_id and x.professional_id=r.professional_id and x.deleted_at is null and m.accepted and x.status='accepted' and x.accepted_at is not null order by x.accepted_at desc,x.id limit 1;
 if found then return jsonb_build_object('stageId','won','evidence',jsonb_build_object('kind','accepted_quote','sourceId',q.id,'at',q.accepted_at));end if;
 select x.* into q from pro_request_quotes m join quotes x on x.id=m.quote_id join professionals p on p.id=x.professional_id and p.profile_id=p_actor where m.owner_id=p_actor and m.request_id=r.id and m.client_user_id=r.client_user_id and x.client_id=r.client_user_id and x.professional_id=r.professional_id and x.deleted_at is null and x.status in('sent','accepted','declined') order by x.created_at desc,x.id limit 1;
 if found then return jsonb_build_object('stageId','estimate_sent','evidence',jsonb_build_object('kind','shared_quote','sourceId',q.id,'at',q.created_at));end if;
 record:=pro_appointment_record(p_actor,r.id);
 if r.status in('confirmed','completed') and not coalesce((record->>'workCancelled')::boolean,false) and record->>'start' is not null then return jsonb_build_object('stageId','meeting_scheduled','evidence',jsonb_build_object('kind','meeting','sourceId',r.id,'at',record->>'start'));end if;
 select * into e from pro_appointment_events where request_id=r.id and actor_id=r.client_user_id and side='client' and action in('accept','reschedule') order by position desc limit 1;if found then return jsonb_build_object('stageId','connected','evidence',jsonb_build_object('kind','client_response','sourceId',e.position::text,'at',e.at));end if;
 select * into e from pro_appointment_events where request_id=r.id and actor_id=p_actor and side='provider' and action in('propose','confirm','decline') order by position desc limit 1;if found then return jsonb_build_object('stageId','followed_up','evidence',jsonb_build_object('kind','provider_response','sourceId',e.position::text,'at',e.at));end if;
 return jsonb_build_object('stageId','new','evidence',jsonb_build_object('kind','new','sourceId',r.id,'at',r.created_at));end $$;
create or replace function public.pro_request_pipeline_lead(p_actor uuid,p_request uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_appointment_requests;state jsonb;automatic jsonb;record jsonb;effective text;followup pro_request_followups;begin
 perform pro_request_pipeline_owner(p_actor);select * into r from pro_appointment_requests where owner_id=p_actor and id=p_request;if not found then raise exception 'Request unavailable' using errcode='P0002';end if;state:=pro_request_pipeline_state(p_actor,p_request);automatic:=pro_request_pipeline_auto(p_actor,p_request);record:=pro_appointment_record(p_actor,p_request);effective:=coalesce(state->>'stageId',automatic->>'stageId');select coalesce(reassign_to_id,effective) into effective from pro_request_pipeline_stages where owner_id=p_actor and id=effective;effective:=coalesce(effective,state->>'stageId',automatic->>'stageId');
 select * into followup from pro_request_followups where owner_id=p_actor and request_id=p_request;
 return jsonb_build_object('requestId',r.id,'position',r.position,'service',r.service,'clientName',r.client_name,'publicStatus',r.status,'requestRevision',r.revision,'createdAt',r.created_at,'updatedAt',r.updated_at,'start',record->'start','workId',r.work_id,'workCancelled',record->'workCancelled','state',state,'effectiveStageId',effective,'automaticStageId',automatic->'stageId','evidence',automatic->'evidence','followup',pro_request_followup_json(followup,r.id));end $$;
-- Relational filtering/counts/token first; only the visible twenty become full
-- lead JSON (including follow-up text). No all-owner business JSON workspace.
create index if not exists pro_request_pipeline_quote_lookup on public.pro_request_quotes(owner_id,request_id,quote_id);
create index if not exists pro_request_pipeline_history_page on public.pro_request_pipeline_history(owner_id,request_id,((after_state->>'revision')::integer) desc);
create or replace function public.pro_request_pipeline_read(p_actor uuid,p_stage text default null,p_query text default '',p_after uuid default null,p_snapshot text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare catalog jsonb;answer jsonb;actual_token text;cursor_valid boolean;begin
 perform pro_request_pipeline_owner(p_actor);catalog:=pro_request_pipeline_catalog(p_actor);if p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage) then raise exception 'Invalid pipeline query' using errcode='22023';end if;
 with base as materialized(
  select r.id,r.position,r.service,r.client_name,r.status,r.revision,r.created_at,r.updated_at,r.requested_start,r.proposed_start,r.professional_id,r.client_user_id,r.work_id,pro_request_pipeline_auto(p_actor,r.id)automatic,coalesce(s.mode,'automatic')mode,s.stage_id,coalesce(s.revision,0)state_revision,s.updated_at state_updated,coalesce(f.revision,0)followup_revision,f.updated_at followup_updated,w.start work_start,w."end" work_end,w.stage work_stage,w.cancelled,
   (select max(position) from pro_appointment_events where request_id=r.id)event_position,
   (select md5(coalesce(string_agg(jsonb_build_array(q.id,q.status,q.updated_at,q.accepted_at,q.deleted_at,q.professional_id,q.client_id,m.client_user_id,m.accepted)::text,',' order by q.id),'')) from pro_request_quotes m join quotes q on q.id=m.quote_id where m.owner_id=p_actor and m.request_id=r.id)quote_token
  from pro_appointment_requests r left join pro_request_pipeline_states s on s.owner_id=p_actor and s.request_id=r.id left join pro_request_followups f on f.owner_id=p_actor and f.request_id=r.id left join pro_work w on w.user_id=p_actor and w.id=r.work_id
  where r.owner_id=p_actor and r.origin='booking' and(btrim(p_query)='' or position(lower(btrim(p_query)) in lower(r.service||' '||r.client_name))>0)
 ),resolved as materialized(select b.*,coalesce(s.reassign_to_id,b.stage_id,b.automatic->>'stageId')effective_stage from base b left join pro_request_pipeline_stages s on s.owner_id=p_actor and s.id=coalesce(b.stage_id,b.automatic->>'stageId')),
 metadata as(select md5(p_actor::text||coalesce(p_stage,'all')||p_query||catalog::text||coalesce(string_agg(jsonb_build_array(id,position,service,client_name,status,revision,created_at,updated_at,requested_start,proposed_start,professional_id,client_user_id,work_id,automatic,mode,stage_id,state_revision,state_updated,followup_revision,followup_updated,work_start,work_end,work_stage,cancelled,event_position,quote_token)::text,',' order by position desc),''))token from resolved),
 anchor as(select position from resolved where id=p_after and(p_stage is null or effective_stage=p_stage)),
 selected as materialized(select id,position from resolved where(p_stage is null or effective_stage=p_stage) and(p_after is null or position<(select position from anchor)) order by position desc limit 21),
 page as(select coalesce(jsonb_agg(pro_request_pipeline_lead(p_actor,id) order by position desc),'[]'::jsonb)items from(select id,position from selected order by position desc limit 20)v),
 counts as(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from resolved where effective_stage=s->>'id')) order by(s->>'position')::integer)items from jsonb_array_elements(catalog->'stages')s)
 select jsonb_build_object('catalog',catalog,'items',page.items,'counts',counts.items,'nextCursor',case when(select count(*) from selected)>20 then(select id from selected order by position desc offset 19 limit 1)else null end,'snapshotToken',metadata.token),metadata.token,(p_after is null or exists(select 1 from anchor)) into answer,actual_token,cursor_valid from page cross join counts cross join metadata;
 if p_after is not null and(p_snapshot is null or p_snapshot<>actual_token or not cursor_valid) then raise exception 'Pipeline changed; reload results' using errcode='40001';end if;return answer;end $$;
create or replace function public.pro_request_pipeline_history_read(p_actor uuid,p_request uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare history jsonb;cursor_revision integer;cursor_id uuid;begin
 perform pro_request_pipeline_owner(p_actor);if not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=p_request) then raise exception 'Request unavailable' using errcode='P0002';end if;
 if p_after is not null then select(after_state->>'revision')::integer into cursor_revision from pro_request_pipeline_history where owner_id=p_actor and request_id=p_request and action_id=p_after;if not found then raise exception 'History cursor unavailable' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_state,'after',h.after_state,'beforeName',h.before_name,'afterName',h.after_name) order by(h.after_state->>'revision')::integer desc),'[]'::jsonb) into history from(select * from pro_request_pipeline_history where owner_id=p_actor and request_id=p_request and(p_after is null or(after_state->>'revision')::integer<cursor_revision) order by(after_state->>'revision')::integer desc limit 21)h;
 if jsonb_array_length(history)>20 then cursor_id:=(history->19->>'actionId')::uuid;history:=history-20;end if;return jsonb_build_object('items',history,'nextCursor',cursor_id);end $$;
create or replace function public.pro_request_pipeline_detail(p_actor uuid,p_request uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare lead jsonb;history jsonb;begin lead:=pro_request_pipeline_lead(p_actor,p_request);history:=pro_request_pipeline_history_read(p_actor,p_request);return jsonb_build_object('catalog',pro_request_pipeline_catalog(p_actor),'lead',lead,'history',history->'items','nextCursor',history->'nextCursor');end $$;
create or replace function public.pro_request_pipeline_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_request_pipeline_actions;begin perform pro_request_pipeline_owner(p_actor);select * into r from pro_request_pipeline_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;if r.input?'requestId' and not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=(r.input->>'requestId')::uuid) then raise exception 'Request unavailable' using errcode='42501';end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_request_pipeline_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare act text;aid uuid;sid text;rid uuid;expected text[];catalog_revision integer;current_revision integer;state_revision integer;catalog jsonb;old_catalog jsonb;before_json jsonb;after_json jsonb;answer jsonb;lead jsonb;auto jsonb;target text;stage_row pro_request_pipeline_stages;ref pro_request_pipeline_states;receipt pro_request_pipeline_actions;position_value integer;reassigned integer:=0;before_name text;after_name text;builtin_order text[];ids text[];begin
 perform pro_request_pipeline_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'catalogRevision') is distinct from 'number' or not coalesce(p_input->>'catalogRevision'~'^[0-9]{1,10}$',false) or(p_input->>'catalogRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid pipeline operation' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;catalog_revision:=(p_input->>'catalogRevision')::integer;
 expected:=case act when 'stage_save' then array['action','actionId','catalogRevision','name','stageId'] when 'stage_reorder' then array['action','actionId','catalogRevision','stageIds'] when 'stage_visibility' then array['action','actionId','catalogRevision','hidden','reassignToId','stageId'] when 'stage_retire' then array['action','actionId','catalogRevision','reassignToId','stageId'] when 'set_stage' then array['action','actionId','catalogRevision','requestId','revision','stageId'] when 'return_auto' then array['action','actionId','catalogRevision','requestId','revision'] else null end;
 if expected is null or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from expected or aid is null then raise exception 'Unexpected pipeline fields' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_request_pipeline_owner(p_actor);
 select * into receipt from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid;if found then if receipt.input is distinct from p_input then raise exception 'Pipeline action reused' using errcode='22023';end if;perform pro_request_pipeline_action_read(p_actor,aid);return receipt.result;end if;
 old_catalog:=pro_request_pipeline_catalog(p_actor);current_revision:=(old_catalog->>'revision')::integer;if current_revision<>catalog_revision then raise exception 'Lead stages changed' using errcode='40001';end if;
 -- Materialize defaults only on an explicit mutation. Reads never backfill.
 insert into pro_request_pipeline_heads values(p_actor,0) on conflict do nothing;
 insert into pro_request_pipeline_stages(owner_id,id,position) select p_actor,v,(n-1)::integer from unnest(array['new','followed_up','connected','meeting_scheduled','estimate_sent','won']) with ordinality x(v,n) on conflict do nothing;
 if act in('set_stage','return_auto') then
  if jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid request state' using errcode='22023';end if;
  rid:=(p_input->>'requestId')::uuid;if not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=rid) then raise exception 'Request unavailable' using errcode='42501';end if;
  before_json:=pro_request_pipeline_state(p_actor,rid);state_revision:=(before_json->>'revision')::integer;if state_revision<>(p_input->>'revision')::integer then raise exception 'Commercial stage changed' using errcode='40001';end if;
  if act='set_stage' then sid:=p_input->>'stageId';select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not hidden and not retired;if not found then raise exception 'Choose an active stage' using errcode='40001';end if;
  else sid:=null;end if;
  select name into before_name from pro_request_pipeline_stages where owner_id=p_actor and id=before_json->>'stageId';
  insert into pro_request_pipeline_states(owner_id,request_id,mode,stage_id,revision) values(p_actor,rid,case when act='set_stage' then 'manual' else 'automatic' end,sid,state_revision+1) on conflict(owner_id,request_id) do update set mode=excluded.mode,stage_id=excluded.stage_id,revision=excluded.revision,updated_at=now();
  after_json:=pro_request_pipeline_state(p_actor,rid);lead:=pro_request_pipeline_lead(p_actor,rid);catalog:=pro_request_pipeline_catalog(p_actor);select value into auto from jsonb_array_elements(catalog->'stages') where value->>'id'=lead->>'effectiveStageId';select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=sid;
  insert into pro_request_pipeline_history values(p_actor,rid,aid,act,before_json,after_json,before_name,after_name,now());answer:=jsonb_build_object('action',act,'catalogRevision',current_revision,'state',after_json,'before',before_json,'stage',auto,'evidence',lead->'evidence');
 else
  if current_revision>=2147483647 then raise exception 'Stage catalogue revision exhausted' using errcode='40001';end if;
  if act='stage_save' then
   if jsonb_typeof(p_input->'stageId') is distinct from 'string' or jsonb_typeof(p_input->'name') is distinct from 'string' or length(btrim(p_input->>'name')) not between 1 and 25 or p_input->>'name'~'[[:cntrl:]]' then raise exception 'Invalid custom stage' using errcode='22023';end if;
   sid:=((p_input->>'stageId')::uuid)::text;select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid;
   if found then if stage_row.retired then raise exception 'Retired stage identity cannot be reused' using errcode='40001';end if;update pro_request_pipeline_stages set name=btrim(p_input->>'name') where owner_id=p_actor and id=sid;
   else if(select count(*) from pro_request_pipeline_stages where owner_id=p_actor and not retired and name is not null)>=12 then raise exception 'Twelve custom stages maximum' using errcode='40001';end if;select count(*) into position_value from pro_request_pipeline_stages where owner_id=p_actor and not retired;insert into pro_request_pipeline_stages(owner_id,id,name,position) values(p_actor,sid,btrim(p_input->>'name'),position_value);end if;
  elsif act='stage_reorder' then
   if jsonb_typeof(p_input->'stageIds') is distinct from 'array' or jsonb_array_length(p_input->'stageIds') not between 6 and 18 or exists(select 1 from jsonb_array_elements(p_input->'stageIds')x where jsonb_typeof(x)<>'string') then raise exception 'Invalid stage order' using errcode='22023';end if;
   select array_agg(value order by ord) into ids from jsonb_array_elements_text(p_input->'stageIds')with ordinality x(value,ord);select array_agg(value order by ord) into builtin_order from jsonb_array_elements_text(p_input->'stageIds')with ordinality x(value,ord) where value in('new','followed_up','connected','meeting_scheduled','estimate_sent','won');
   if builtin_order is distinct from array['new','followed_up','connected','meeting_scheduled','estimate_sent','won'] or cardinality(ids)<>(select count(distinct x) from unnest(ids)x) or cardinality(ids)<>(select count(*) from pro_request_pipeline_stages where owner_id=p_actor and not retired) or exists(select 1 from unnest(ids)x where not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=x and not retired)) then raise exception 'Stage order changed' using errcode='40001';end if;
   update pro_request_pipeline_stages s set position=x.ord-1 from unnest(ids)with ordinality x(id,ord) where s.owner_id=p_actor and s.id=x.id;
  else
   if jsonb_typeof(p_input->'stageId') is distinct from 'string' or jsonb_typeof(p_input->'reassignToId') not in('string','null') then raise exception 'Invalid stage visibility' using errcode='22023';end if;
   sid:=p_input->>'stageId';target:=p_input->>'reassignToId';select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not retired;if not found then raise exception 'Stage unavailable' using errcode='40001';end if;
   if act='stage_retire' then if stage_row.name is null then raise exception 'Built-in stages cannot be retired' using errcode='22023';end if;
   elsif jsonb_typeof(p_input->'hidden') is distinct from 'boolean' or(p_input->>'hidden')::boolean=stage_row.hidden or sid in('new','won') and(p_input->>'hidden')::boolean then raise exception 'Invalid stage visibility transition' using errcode='22023';end if;
   if act='stage_retire' or(p_input->>'hidden')::boolean then
    if target is null or target=sid or not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=target and not hidden and not retired) then raise exception 'Choose a visible replacement stage' using errcode='40001';end if;
    select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=target;
    for ref in select * from pro_request_pipeline_states where owner_id=p_actor and mode='manual' and stage_id=sid order by request_id for update loop
     if ref.revision>=2147483647 then raise exception 'Request stage revision exhausted' using errcode='40001';end if;before_json:=pro_request_pipeline_state(p_actor,ref.request_id);update pro_request_pipeline_states set stage_id=target,revision=revision+1,updated_at=now() where owner_id=p_actor and request_id=ref.request_id;after_json:=pro_request_pipeline_state(p_actor,ref.request_id);insert into pro_request_pipeline_history values(p_actor,ref.request_id,aid,'reassign_stage',before_json,after_json,stage_row.name,after_name,now());reassigned:=reassigned+1;
    end loop;
    update pro_request_pipeline_stages set reassign_to_id=target where owner_id=p_actor and hidden and reassign_to_id=sid;
    update pro_request_pipeline_stages set hidden=true,reassign_to_id=target,retired=(act='stage_retire') where owner_id=p_actor and id=sid;
    if act='stage_retire' then with ordered as(select id,row_number()over(order by position)-1 pos from pro_request_pipeline_stages where owner_id=p_actor and not retired)update pro_request_pipeline_stages s set position=o.pos from ordered o where s.owner_id=p_actor and s.id=o.id;end if;
   else if target is not null then raise exception 'Showing a stage needs no reassignment' using errcode='22023';end if;update pro_request_pipeline_stages set hidden=false,reassign_to_id=null where owner_id=p_actor and id=sid;end if;
  end if;
  update pro_request_pipeline_heads set revision=current_revision+1 where owner_id=p_actor;catalog:=pro_request_pipeline_catalog(p_actor);answer:=jsonb_build_object('action',act,'catalog',catalog,'reassigned',reassigned);
 end if;
 perform pro_request_pipeline_owner(p_actor);insert into pro_request_pipeline_actions(owner_id,action_id,input,result,actor_name) values(p_actor,aid,p_input,answer,pro_team_name(p_actor));perform pro_request_pipeline_owner(p_actor);return answer;end $$;
create or replace function public.pro_request_pipeline_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception 'Immutable pipeline audit' using errcode='23514';end $$;
drop trigger if exists pro_request_pipeline_immutable on public.pro_request_pipeline_history;
create trigger pro_request_pipeline_immutable before update on public.pro_request_pipeline_history for each row execute function pro_request_pipeline_immutable();
drop trigger if exists pro_request_pipeline_immutable on public.pro_request_pipeline_actions;
create trigger pro_request_pipeline_immutable before update on public.pro_request_pipeline_actions for each row execute function pro_request_pipeline_immutable();
do $$declare t text;f record;begin foreach t in array array['pro_request_pipeline_heads','pro_request_pipeline_stages','pro_request_pipeline_states','pro_request_pipeline_actions','pro_request_pipeline_history'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro_request_pipeline_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
